CREATE TABLE IF NOT EXISTS agent_schedules (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, requested_by text NOT NULL, agent_config_id text NOT NULL, rule text NOT NULL, timezone text NOT NULL, status text NOT NULL DEFAULT 'active', next_run_at timestamptz, version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, CONSTRAINT agent_schedules_status_check CHECK (status IN ('active','paused','deleted')));
CREATE INDEX IF NOT EXISTS idx_agent_schedules_owner ON agent_schedules (requested_by, workspace_id, updated_at DESC);
CREATE TABLE IF NOT EXISTS schedule_triggers (id text PRIMARY KEY, schedule_id text NOT NULL REFERENCES agent_schedules(id) ON DELETE CASCADE, due_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'pending', agent_task_id text, error_code text, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, UNIQUE(schedule_id,due_at));
